<?php
require __DIR__ . '/../app/bootstrap.php'; require_login();
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $id=(int)($_POST['id']??0); $action=(string)($_POST['action']??'');
 if ($action==='delete') { $q=db()->prepare('DELETE FROM items WHERE id=? AND user_id=?'); $q->execute([$id,current_user()['id']]); flash($q->rowCount()?'Listing deleted.':'Listing was not found.','info'); }
 elseif ($action==='close') { $q=db()->prepare("UPDATE items SET status='Returned' WHERE id=? AND user_id=? AND status='Open'"); $q->execute([$id,current_user()['id']]); flash('Listing marked as returned.'); }
 elseif ($action==='reopen') { $q=db()->prepare("UPDATE items SET status='Open' WHERE id=? AND user_id=? AND status='Returned'"); $q->execute([$id,current_user()['id']]); flash('Listing reopened.'); }
 redirect('my-items.php'); }
$q=db()->prepare("SELECT i.*, (SELECT COUNT(*) FROM claims c WHERE c.item_id=i.id AND c.status='Pending') AS pending_claims FROM items i WHERE i.user_id=? ORDER BY i.created_at DESC"); $q->execute([current_user()['id']]); $items=$q->fetchAll();
page_start('My items','mine'); ?><div class="section-head"><div><span class="eyebrow">YOUR ACTIVITY</span><h1>My items</h1><p class="muted">Manage your listings and review claims on items you found.</p></div><a class="button" href="item-form.php">＋ Post an item</a></div><?php if(!$items): ?><div class="empty-state"><span>＋</span><h3>Your board starts here</h3><p>Post a lost or found item and the campus community can help.</p><a class="button" href="item-form.php">Create your first listing</a></div><?php else: ?><div class="my-listings"><?php foreach($items as $item): ?><article class="listing-row"><div class="listing-main"><span class="badge <?= $item['kind']==='Lost'?'badge-lost':'badge-found' ?>"><?= e($item['kind']) ?></span><h3><a href="item.php?id=<?= (int)$item['id'] ?>"><?= e($item['title']) ?></a></h3><p><?= e($item['category']) ?> · <?= e($item['location']) ?> · <?= e(format_date($item['event_date'])) ?></p></div><span class="status status-<?= e(strtolower($item['status'])) ?>"><?= e($item['status']) ?></span><div class="listing-actions"><a class="text-link" href="item-form.php?id=<?= (int)$item['id'] ?>">Edit</a><?php if((int)$item['pending_claims']>0): ?><a class="text-link" href="item.php?id=<?= (int)$item['id'] ?>#claims"><?= (int)$item['pending_claims'] ?> claim(s)</a><?php endif; ?><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><?php if($item['status']==='Open'): ?><button name="action" value="close" class="text-button">Mark returned</button><?php else: ?><button name="action" value="reopen" class="text-button">Reopen</button><?php endif; ?><button name="action" value="delete" class="text-button danger" data-confirm="Delete this listing and its claim history?">Delete</button></form></div></article><?php endforeach; ?></div><?php endif; ?><?php page_end(); ?>
